#!/usr/bin/env node
// WebOperator framed JSON client for agents.
const net = require('net');
const { randomUUID } = require('crypto');

const socketPath = process.env.WEBOPERATOR_AGENT_SOCKET || '/tmp/weboperator-bridge.sock';
const token = <REDACTED> || '';
const input = process.argv[2] ? JSON.parse(process.argv[2]) : { type: 'bridge.health' };
const message = {
  id: input.id || randomUUID(),
  type: input.type || 'bridge.health',
  payload: input.payload || {},
  timeoutMs: input.timeoutMs,
  ...(token ? { token } : {}),
};

let buffer = Buffer.alloc(0);
let nextFrameLength = null;
const socket = net.createConnection(socketPath, () => sendFrame(socket, message));

socket.on('data', (chunk) => {
  buffer = Buffer.concat([buffer, chunk]);
  readFrames();
});
socket.on('error', (err) => {
  console.error(err.message);
  process.exitCode = 1;
});

function readFrames() {
  while (true) {
    if (nextFrameLength === null) {
      if (buffer.length < 4) return;
      nextFrameLength = buffer.readUInt32LE(0);
      buffer = buffer.slice(4);
    }
    if (buffer.length < nextFrameLength) return;
    const payload = buffer.slice(0, nextFrameLength).toString('utf8');
    buffer = buffer.slice(nextFrameLength);
    nextFrameLength = null;
    const msg = JSON.parse(payload);
    if (msg.kind === 'event') {
      console.error(JSON.stringify(msg));
      continue;
    }
    console.log(JSON.stringify(msg, null, 2));
    socket.end();
  }
}

function sendFrame(sock, obj) {
  const body = Buffer.from(JSON.stringify(obj), 'utf8');
  const header = Buffer.alloc(4);
  header.writeUInt32LE(body.length, 0);
  sock.write(Buffer.concat([header, body]));
}

#!/usr/bin/env node
/**
 * WebOperator MCP (Model Context Protocol) Server
 * Industry-standard tool provider for AI agents (Hermes, OpenClaw, Claude Desktop, Cursor, OpenHands).
 * Communicates over STDIO using standard JSON-RPC 2.0.
 */

const net = require('net');
const http = require('http');
const readline = require('readline');
const { randomUUID } = require('crypto');

const { version: SERVER_VERSION } = require('./package.json');

const SOCKET_PATH = process.env.WEBOPERATOR_AGENT_SOCKET || '/tmp/weboperator-bridge.sock';
const BRIDGE_HOST = process.env.WEBOPERATOR_BRIDGE_HOST || '127.0.0.1';
const BRIDGE_PORT = Number(process.env.WEBOPERATOR_BRIDGE_PORT || 8765);
const API_TOKEN = <REDACTED> || '';

process.stdout.on('error', (err) => {
  if (err && err.code === 'EPIPE') process.exit(0);
});
process.on('uncaughtException', (err) => {
  if (err && (err.code === 'EPIPE' || err.code === 'ERR_STREAM_DESTROYED')) process.exit(0);
});


const TOOLS = [
  {
    name: 'browser_snapshot',
    description: 'Capture the structured accessibility tree and numbered interactive elements (buttons, inputs, links) from the current active browser tab.',
    inputSchema: {
      type: 'object',
      properties: {},
      additionalProperties: false,
    },
  },
  {
    name: 'browser_navigate',
    description: 'Navigate the active browser tab to a specified URL.',
    inputSchema: {
      type: 'object',
      properties: {
        url: {
          type: 'string',
          description: 'The URL to navigate to (e.g. "https://google.com").',
        },
      },
      required: ['url'],
      additionalProperties: false,
    },
  },
  {
    name: 'browser_click',
    description: 'Click an element on the webpage by its numeric index (from browser_snapshot) or CSS selector.',
    inputSchema: {
      type: 'object',
      properties: {
        index: {
          type: 'number',
          description: 'The numeric index of the interactive element from the snapshot.',
        },
        selector: {
          type: 'string',
          description: 'Alternative CSS selector of the element to click.',
        },
      },
      additionalProperties: false,
    },
  },
  {
    name: 'browser_type',
    description: 'Type text into an input field by element index or selector.',
    inputSchema: {
      type: 'object',
      properties: {
        index: {
          type: 'number',
          description: 'The numeric index of the input element from the snapshot.',
        },
        selector: {
          type: 'string',
          description: 'Alternative CSS selector of the input element.',
        },
        text: {
          type: 'string',
          description: 'The text to type into the field.',
        },
        clear: {
          type: 'boolean',
          description: 'Whether to clear existing text before typing (default: false).',
        },
      },
      required: ['text'],
      additionalProperties: false,
    },
  },
  {
    name: 'browser_press',
    description: 'Press a keyboard key on the active webpage (e.g. "Enter", "Tab", "Escape", "ArrowDown", "Backspace").',
    inputSchema: {
      type: 'object',
      properties: {
        key: {
          type: 'string',
          description: 'The key to press (e.g. "Enter", "Tab", "Escape").',
        },
      },
      required: ['key'],
      additionalProperties: false,
    },
  },
  {
    name: 'browser_scroll',
    description: 'Scroll the active webpage up or down.',
    inputSchema: {
      type: 'object',
      properties: {
        direction: {
          type: 'string',
          enum: ['down', 'up'],
          description: 'Direction to scroll (default: "down").',
        },
        amount: {
          type: 'number',
          description: 'Number of pixels to scroll (default: 500).',
        },
      },
      additionalProperties: false,
    },
  },
  {
    name: 'browser_screenshot',
    description: 'Capture a visual PNG screenshot of the current active browser tab.',
    inputSchema: {
      type: 'object',
      properties: {},
      additionalProperties: false,
    },
  },
  {
    name: 'browser_extract',
    description: 'Extract text or structured data from the webpage according to an extraction instruction.',
    inputSchema: {
      type: 'object',
      properties: {
        instruction: {
          type: 'string',
          description: 'Extraction guidance or prompt (e.g. "Extract all product prices and titles").',
        },
        selector: {
          type: 'string',
          description: 'Optional CSS selector to scope extraction.',
        },
      },
      additionalProperties: false,
    },
  },
  {
    name: 'browser_solve_captcha',
    description: 'Attempt to detect and automatically solve or click Cloudflare Turnstile, reCAPTCHA, hCaptcha, slider puzzle, or visual text challenges in the active tab.',
    inputSchema: {
      type: 'object',
      properties: {
        type: {
          type: 'string',
          enum: ['cloudflare', 'recaptcha', 'hcaptcha', 'slider', 'image', 'audio', 'press_and_hold', 'pow', 'auto'],
          description: 'Optional captcha type to target (default: auto).',
        },
      },
      additionalProperties: false,
    },
  },
  {
    name: 'weboperator_execute_goal',
    description: 'Execute an autonomous browser goal end-to-end using WebOperator multi-step planner.',
    inputSchema: {
      type: 'object',
      properties: {
        goal: {
          type: 'string',
          description: 'Natural language goal for the agent to achieve (e.g. "Find cheapest flight from Paris to Rome on Kayak").',
        },
        timeoutMs: {
          type: 'number',
          description: 'Maximum timeout in milliseconds (default: 120000).',
        },
      },
      required: ['goal'],
      additionalProperties: false,
    },
  },
];

async function callBridge(type, payload = {}, timeoutMs = 60_000) {
  // Try Unix Domain Socket first
  try {
    return await callSocket(type, payload, timeoutMs);
  } catch (err) {
    // Once the bridge has taken the request, its answer is the answer. A
    // retry over HTTP would hide the real error behind whatever the second
    // attempt says, and after a timeout it would run the action again — a
    // second click, a second form submission.
    if (err && err.reachedBridge) throw err;
    // The socket could not be opened at all: fall back to the HTTP API.
    return await callHttp(type, payload, timeoutMs);
  }
}

// The socket takes the extension's own request types; the HTTP API has its
// own routes and tool names. This is the translation between the two.
function httpRequestFor(type, payload, timeoutMs) {
  if (type === 'tasks.start') {
    return { path: '/v1/tasks', body: payload };
  }
  if (type === 'tasks.wait') {
    return {
      path: `/v1/tasks/${encodeURIComponent(payload.id)}/wait`,
      body: { timeoutMs: payload.timeoutMs },
    };
  }
  // browser.snapshot -> browser_snapshot, and so on for every browser tool.
  return {
    path: '/v1/tools/call',
    body: { tool: type.replace('.', '_'), arguments: payload, timeoutMs },
  };
}


function callSocket(type, payload, timeoutMs) {
  return new Promise((resolve, reject) => {
    let resolved = false;
    let connected = false;
    const fail = (err) => reject(Object.assign(err, { reachedBridge: connected }));
    const socket = net.createConnection(SOCKET_PATH);
    const id = randomUUID();
    const message = { id, type, payload, timeoutMs, ...(API_TOKEN ? { token: <REDACTED> } : {}) };

    const timer = setTimeout(() => {
      if (!resolved) {
        resolved = true;
        socket.destroy();
        fail(new Error(`Bridge socket timeout for ${type}`));
      }
    }, timeoutMs);

    let buffer = Buffer.alloc(0);
    let nextLength = null;

    socket.on('connect', () => {
      connected = true;
      const body = Buffer.from(JSON.stringify(message), 'utf8');
      const header = Buffer.alloc(4);
      header.writeUInt32LE(body.length, 0);
      socket.write(Buffer.concat([header, body]));
    });

    socket.on('data', (chunk) => {
      buffer = Buffer.concat([buffer, chunk]);
      while (true) {
        if (nextLength === null) {
          if (buffer.length < 4) return;
          nextLength = buffer.readUInt32LE(0);
          buffer = buffer.slice(4);
        }
        if (buffer.length < nextLength) return;
        const raw = buffer.slice(0, nextLength).toString('utf8');
        buffer = buffer.slice(nextLength);
        nextLength = null;

        try {
          const msg = JSON.parse(raw);
          if (msg.kind === 'event') continue;
          if (!resolved) {
            resolved = true;
            clearTimeout(timer);
            socket.end();
            if (msg.error) fail(new Error(msg.error));
            else resolve(msg.result);
          }
        } catch (parseErr) {
          if (!resolved) {
            resolved = true;
            clearTimeout(timer);
            socket.destroy();
            fail(parseErr);
          }
        }
      }
    });

    socket.on('error', (err) => {
      if (!resolved) {
        resolved = true;
        clearTimeout(timer);
        fail(err);
      }
    });
  });
}

function callHttp(type, payload, timeoutMs) {
  return new Promise((resolve, reject) => {
    const { path, body: bodyObj } = httpRequestFor(type, payload, timeoutMs);
    const method = 'POST';

    const headers = {
      'content-type': 'application/json',
      ...(API_TOKEN ? { authorization: `Bearer ${API_TOKEN}`, 'x-weboperator-token': API_TOKEN } : {}),
    };

    const req = http.request({
      host: BRIDGE_HOST,
      port: BRIDGE_PORT,
      path,
      method,
      headers,
      timeout: timeoutMs,
    }, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        try {
          const json = JSON.parse(data);
          if (res.statusCode && res.statusCode >= 400) {
            reject(new Error(json.error || `HTTP ${res.statusCode}`));
          } else {
            resolve(json.result !== undefined ? json.result : json);
          }
        } catch {
          reject(new Error(`Failed to parse HTTP bridge response: ${data}`));
        }

      });
    });

    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy();
      reject(new Error(`HTTP bridge timeout for ${type}`));
    });

    req.write(JSON.stringify(bodyObj));
    req.end();
  });
}

async function handleToolCall(name, args) {
  switch (name) {
    case 'browser_snapshot': {
      const res = await callBridge('browser.snapshot', {}, 30_000);
      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify(res, null, 2),
          },
        ],
      };
    }
    case 'browser_navigate': {
      const res = await callBridge('browser.navigate', { url: args.url }, 60_000);
      return {
        content: [
          {
            type: 'text',
            text: `Navigated to ${args.url}. Current title: ${res?.title || ''}`,
          },
        ],
      };
    }
    case 'browser_click': {
      const res = await callBridge('browser.click', { index: args.index, selector: args.selector }, 30_000);
      return {
        content: [
          {
            type: 'text',
            text: `Clicked element. ${res?.status || 'ok'}`,
          },
        ],
      };
    }
    case 'browser_type': {
      const res = await callBridge('browser.type', { index: args.index, selector: args.selector, text: args.text, clear: args.clear }, 30_000);
      return {
        content: [
          {
            type: 'text',
            text: `Typed into element: "${args.text}". ${res?.status || 'ok'}`,
          },
        ],
      };
    }
    case 'browser_press': {
      const res = await callBridge('browser.press', { key: args.key }, 30_000);
      return {
        content: [
          {
            type: 'text',
            text: `Pressed key "${args.key}". ${res?.status || 'ok'}`,
          },
        ],
      };
    }
    case 'browser_scroll': {
      const res = await callBridge('browser.scroll', { direction: args.direction || 'down', amount: args.amount || 500 }, 30_000);
      return {
        content: [
          {
            type: 'text',
            text: `Scrolled ${args.direction || 'down'}. ${res?.status || 'ok'}`,
          },
        ],
      };
    }
    case 'browser_screenshot': {
      const res = await callBridge('browser.screenshot', {}, 30_000);
      const dataUri = res?.dataUri || res?.screenshot || '';
      const base64Data = dataUri.replace(/^data:image\/[a-z]+;base64,/, '');
      if (base64Data) {
        return {
          content: [
            {
              type: 'image',
              data: base64Data,
              mimeType: 'image/png',
            },
          ],
        };
      }
      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify(res, null, 2),
          },
        ],
      };
    }
    case 'browser_extract': {
      const res = await callBridge('browser.extract', { instruction: args.instruction, selector: args.selector }, 30_000);
      return {
        content: [
          {
            type: 'text',
            text: typeof res === 'string' ? res : JSON.stringify(res, null, 2),
          },
        ],
      };
    }
    case 'browser_solve_captcha': {
      const res = await callBridge('browser.solve_captcha', { type: args.type === 'auto' ? undefined : args.type }, 30_000);
      return {
        content: [
          {
            type: 'text',
            text: typeof res === 'string' ? res : JSON.stringify(res, null, 2),
          },
        ],
      };
    }
    case 'weboperator_execute_goal': {
      const taskTimeout = Number(args.timeoutMs || 120_000);
      const startRes = await callBridge('tasks.start', { goal: args.goal, timeoutMs: taskTimeout }, 30_000);
      const taskId = startRes && startRes.id;
      let finalTask = startRes;
      if (taskId) {
        finalTask = await callBridge('tasks.wait', { id: taskId, timeoutMs: taskTimeout }, taskTimeout + 10_000);
      }
      const formatted = formatTaskResultForAgent(finalTask || startRes);
      const responseText = formatted.answer || JSON.stringify(formatted, null, 2);
      return {
        content: [
          {
            type: 'text',
            text: responseText,
          },
        ],
      };
    }
    default:
      throw new Error(`Unknown tool: ${name}`);
  }
}

function formatTaskResultForAgent(task) {
  if (!task) return { ok: false, status: 'failed', error: 'Task not found or timed out' };

  const steps = Array.isArray(task.steps) ? task.steps : [];
  let answer = '';
  const extractedList = [];

  for (const step of steps) {
    if (step.toolCall) {
      const args = step.toolCall.arguments || {};
      if (step.toolCall.name === 'done') {
        if (args.answer || args.text || args.note || args.summary) {
          answer = String(args.answer || args.text || args.note || args.summary);
        }
      }
      if (step.toolCall.name === 'extract' && args.instruction) {
        if (step.result && step.result.extracted) {
          extractedList.push(step.result.extracted);
        }
      }
    }
    if (step.result && step.result.extracted !== undefined) {
      extractedList.push(step.result.extracted);
    }
    if (!answer && step.note && step.status === 'ok') {
      answer = step.note;
    }
  }

  if (!answer && extractedList.length > 0) {
    answer = typeof extractedList[extractedList.length - 1] === 'string'
      ? extractedList[extractedList.length - 1]
      : JSON.stringify(extractedList, null, 2);
  }

  if (!answer && task.plan && Array.isArray(task.plan.steps)) {
    const doneSteps = task.plan.steps.filter((s) => s.status === 'done');
    if (doneSteps.length > 0) {
      answer = doneSteps.map((s) => `✓ ${s.description}`).join('\n');
    }
  }

  if (!answer && task.status === 'done') {
    answer = `Goal completed successfully: "${task.goal}"`;
  } else if (!answer && task.status === 'failed') {
    answer = `Goal failed: ${task.error || 'Unknown error'}`;
  }

  return {
    ok: task.status === 'done',
    status: task.status,
    goal: task.goal,
    answer,
    extracted: extractedList.length > 0 ? extractedList : undefined,
    stepCount: steps.length,
    error: task.error,
    modelUsed: task.modelUsed,
  };
}


function sendJsonRpc(obj) {
  const line = JSON.stringify(obj) + '\n';
  process.stdout.write(line);
}

function sendResponse(id, result) {
  sendJsonRpc({ jsonrpc: '2.0', id, result });
}

function sendError(id, code, message, data) {
  sendJsonRpc({ jsonrpc: '2.0', id, error: { code, message, ...(data ? { data } : {}) } });
}

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false,
});

rl.on('line', async (line) => {
  const trimmed = line.trim();
  if (!trimmed) return;

  let msg;
  try {
    msg = JSON.parse(trimmed);
  } catch {
    sendError(null, -32700, 'Parse error');
    return;
  }


  const { id, method, params } = msg;

  if (method === 'initialize') {
    sendResponse(id, {
      protocolVersion: '2024-11-05',
      capabilities: {
        tools: {
          listChanged: false,
        },
      },
      serverInfo: {
        name: 'weboperator-mcp',
        version: SERVER_VERSION,
      },
    });
    return;
  }

  if (method === 'notifications/initialized' || method === 'initialized') {
    // Client notification, no response required
    return;
  }

  if (method === 'ping') {
    sendResponse(id, {});
    return;
  }

  if (method === 'tools/list') {
    sendResponse(id, { tools: TOOLS });
    return;
  }

  if (method === 'tools/call') {
    const { name, arguments: toolArgs } = params || {};
    try {
      const result = await handleToolCall(name, toolArgs || {});
      sendResponse(id, result);
    } catch (err) {
      sendResponse(id, {
        isError: true,
        content: [
          {
            type: 'text',
            text: err instanceof Error ? err.message : String(err),
          },
        ],
      });
    }
    return;
  }

  if (id !== undefined) {
    sendError(id, -32601, `Method not found: ${method}`);
  }
});

import { describe, expect, it, vi } from 'vitest';
import { chatAnthropic } from './anthropic-client';

describe('chatAnthropic', () => {
  it('throws error when api key is missing', async () => {
    await expect(
      chatAnthropic(
        { url: '', model: 'claude-3-7-sonnet-20250219', messages: [{ role: 'user', content: 'hello' }] },
        '',
        'claude-3-7-sonnet-20250219'
      )
    ).rejects.toThrow('Anthropic API key is empty');
  });

  it('formats payload correctly and returns tool call response', async () => {
    const mockFetch = vi.fn().mockResolvedValue({
      ok: true,
      json: async () => ({
        content: [
          { type: 'text', text: 'I will click on the button.' },
          { type: 'tool_use', id: 'tool_123', name: 'click', input: { ref: '@e5', reason: 'Submit' } },
        ],
        usage: { output_tokens: <REDACTED> },
      }),
    });

    vi.stubGlobal('fetch', mockFetch);

    const result = await chatAnthropic(
      {
        url: '',
        model: 'claude-3-7-sonnet-20250219',
        messages: [
          { role: 'system', content: 'You are a browser agent.' },
          { role: 'user', content: 'Click submit' },
        ],
      },
      'sk-ant-test-key-12345',
      'claude-3-7-sonnet-20250219'
    );

    expect(mockFetch).toHaveBeenCalledWith(
      'https://api.anthropic.com/v1/messages',
      expect.objectContaining({
        method: 'POST',
        headers: expect.objectContaining({
          'x-api-key': 'sk-ant-test-key-12345',
          'anthropic-version': '2023-06-01',
        }),
      })
    );

    expect(result.content).toBe('I will click on the button.');
    expect(result.toolCall).toEqual({
      name: 'click',
      arguments: { ref: '@e5', reason: 'Submit' },
      id: 'tool_123',
    });
    expect(result.evalCount).toBe(42);
  });

  it('parses extended thinking blocks for Claude 3.7 models', async () => {
    const mockFetch = vi.fn().mockResolvedValue({
      ok: true,
      json: async () => ({
        content: [
          { type: 'thinking', thinking: 'Let me analyze the DOM structure...' },
          { type: 'tool_use', id: 'tool_999', name: 'navigate', input: { url: 'https://example.com' } },
        ],
        usage: { output_tokens: <REDACTED> },
      }),
    });

    vi.stubGlobal('fetch', mockFetch);

    const onUpdate = vi.fn();
    const result = await chatAnthropic(
      {
        url: '',
        model: 'claude-3-7-sonnet-20250219',
        thinking: true,
        onUpdate,
        messages: [{ role: 'user', content: 'Go to example.com' }],
      },
      'sk-ant-test-key-12345',
      'claude-3-7-sonnet-20250219'
    );

    expect(result.thinking).toBe('Let me analyze the DOM structure...');
    expect(result.toolCall?.name).toBe('navigate');
    expect(onUpdate).toHaveBeenCalledWith(expect.objectContaining({
      thinking: 'Let me analyze the DOM structure...',
    }));
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { chatMlx } from './mlx-client';

const OK = { status: 200, headers: { 'content-type': 'application/json' } };

function reply(message: Record<string, unknown>) {
  return vi.fn(async () => new Response(JSON.stringify({ choices: [{ message }] }), OK));
}

describe('mlx-client', () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('caps output length so one step fits the request timeout', async () => {
    // Without this the server applies its own 2048 default, which an 8B cannot finish
    // inside the 120s abort — the step hangs instead of answering.
    const bodies: Array<Record<string, unknown>> = [];
    vi.stubGlobal('fetch', vi.fn(async (_url: string, init: RequestInit) => {
      bodies.push(JSON.parse(String(init.body)) as Record<string, unknown>);
      return new Response(JSON.stringify({ choices: [{ message: { content: 'ok' } }] }), OK);
    }));

    await chatMlx({ url: '', model: 'm', messages: [] }, '', 'm');
    expect(bodies[0].max_tokens).toBe(1024);
  });

  it('passes the thinking policy through, defaulting it off', async () => {
    const bodies: Array<Record<string, unknown>> = [];
    vi.stubGlobal('fetch', vi.fn(async (_url: string, init: RequestInit) => {
      bodies.push(JSON.parse(String(init.body)) as Record<string, unknown>);
      return new Response(JSON.stringify({ choices: [{ message: { content: 'ok' } }] }), OK);
    }));

    await chatMlx({ url: '', model: 'm', messages: [], thinking: true }, '', 'm');
    await chatMlx({ url: '', model: 'm', messages: [] }, '', 'm');
    expect(bodies.map((b) => b.enable_thinking)).toEqual([true, false]);
  });

  it('reads a native tool call from tool_calls', async () => {
    vi.stubGlobal('fetch', reply({
      content: '',
      tool_calls: [{ id: 'call_1', function: { name: 'done', arguments: '{"success":true}' } }],
    }));

    const res = await chatMlx({ url: '', model: 'm', messages: [] }, '', 'm');
    expect(res.toolCall?.name).toBe('done');
    expect(res.toolCall?.arguments).toEqual({ success: true });
    expect(res.toolCallSource).toBe('native');
  });

  // mlx-vlm serving Qwen3-VL routinely returns the call as plain text with tool_calls empty.
  // Before the fallback this failed the step outright, after a wasted repair round-trip.
  it('recovers a tool call the model wrote into the content', async () => {
    vi.stubGlobal('fetch', reply({
      content: '{"name": "done", "arguments": {"success": true, "summary": "clear, 18C"}}',
    }));

    const res = await chatMlx({ url: '', model: 'm', messages: [] }, '', 'm');
    expect(res.toolCall?.name).toBe('done');
    expect(res.toolCall?.arguments).toEqual({ success: true, summary: 'clear, 18C' });
    expect(res.toolCallSource).toBe('content');
  });

  it('recovers a tool call wrapped in a json code fence', async () => {
    vi.stubGlobal('fetch', reply({
      content: '```json\n{"name": "type", "arguments": {"ref": "@e12", "text": "hi"}}\n```',
    }));

    const res = await chatMlx({ url: '', model: 'm', messages: [] }, '', 'm');
    expect(res.toolCall?.name).toBe('type');
    expect(res.toolCallSource).toBe('content');
  });

  it('leaves prose alone rather than inventing a call', async () => {
    vi.stubGlobal('fetch', reply({ content: 'I should click the search box next.' }));

    const res = await chatMlx({ url: '', model: 'm', messages: [] }, '', 'm');
    expect(res.toolCall).toBeUndefined();
    expect(res.toolCallSource).toBeUndefined();
  });

  it('ignores JSON that is not one of the agent tools', async () => {
    vi.stubGlobal('fetch', reply({ content: '{"name": "not_a_tool", "arguments": {}}' }));

    const res = await chatMlx({ url: '', model: 'm', messages: [] }, '', 'm');
    expect(res.toolCall).toBeUndefined();
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { normalizeOllamaUrl, ollamaOriginsValue, ping, resolveNumCtx, chat } from './ollama-client';

describe('ollama-client', () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('normalizes URLs without protocol to http://', () => {
    expect(normalizeOllamaUrl('localhost:11434')).toBe('http://localhost:11434');
    expect(normalizeOllamaUrl('127.0.0.1:11434/')).toBe('http://127.0.0.1:11434');
    expect(normalizeOllamaUrl('https://my-ollama.example.com/')).toBe('https://my-ollama.example.com');
    expect(normalizeOllamaUrl('')).toBe('');
  });

  it('resolves num_ctx to a floor that fits a screenshot step, and honours an explicit request', () => {
    expect(resolveNumCtx()).toBe(16384);
    expect(resolveNumCtx(32768)).toBe(32768);
    // 0 is the "unset" setting value, and anything below the floor is unusable for one
    // screenshot-bearing step, so both fall back rather than being sent as asked.
    expect(resolveNumCtx(0)).toBe(16384);
    expect(resolveNumCtx(2048)).toBe(16384);
  });

  it('names the concrete extension origin in the 403 hint, never a wildcard', () => {
    // A wildcard is the one value that cannot work: Ollama accepts `chrome-extension://*` into
    // OLLAMA_ORIGINS and then still answers 403, so suggesting it repeats the error.
    vi.stubGlobal('chrome', { runtime: { id: 'phbohkmfojcjbmgfnaikenmgemgckdpg' } });
    expect(ollamaOriginsValue()).toContain('chrome-extension://phbohkmfojcjbmgfnaikenmgemgckdpg');
    expect(ollamaOriginsValue()).not.toContain('chrome-extension://*');

    vi.unstubAllGlobals();
    // Off a page — the eval harness, a unit test — there is no id to name, so the value stays a
    // placeholder the user can fill rather than a wildcard they would paste verbatim.
    expect(ollamaOriginsValue()).not.toContain('chrome-extension://*');
  });

  it('returns ok: false without throwing when ping is given an unsupported scheme/model string', async () => {
    const result = await ping('glm-5.3-flash:cloud');
    expect(result.ok).toBe(false);
    expect(result.models).toEqual([]);
    expect(result.error).toBeDefined();
  });

  it('handles empty or whitespace url gracefully in ping', async () => {
    const result = await ping('   ');
    expect(result.ok).toBe(false);
    expect(result.error).toContain('empty');
  });

  it('retries without the thinking flag when the model rejects it, then remembers', async () => {
    const bodies: Array<Record<string, unknown>> = [];
    const fetchMock = vi.fn(async (_url: string, init: RequestInit) => {
      const body = JSON.parse(String(init.body)) as Record<string, unknown>;
      bodies.push(body);
      if (body.think === true) {
        return new Response(JSON.stringify({ error: '"no-think-model" does not support thinking' }), { status: 400 });
      }
      return new Response(JSON.stringify({ message: { content: 'ok' }, model: 'no-think-model' }), {
        status: 200,
        headers: { 'content-type': 'application/json' },
      });
    });
    vi.stubGlobal('fetch', fetchMock);

    const first = await chat({ url: 'http://127.0.0.1:11434', model: 'no-think-model', messages: [], thinking: true });
    expect(first.content).toBe('ok');
    expect(bodies.map((body) => body.think)).toEqual([true, false]);

    // The rejection is remembered, so the next call asks for no thinking up front.
    await chat({ url: 'http://127.0.0.1:11434', model: 'no-think-model', messages: [], thinking: true });
    expect(bodies.map((body) => body.think)).toEqual([true, false, false]);
  });

  it('keeps a 400 that is not about thinking as an error', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => new Response('model not found', { status: 400 })));

    await expect(
      chat({ url: 'http://127.0.0.1:11434', model: 'missing-model', messages: [], thinking: true }),
    ).rejects.toThrow(/Ollama 400: model not found/);
  });

  it('never sends the thinking flag when the caller did not ask for it', async () => {
    const bodies: Array<Record<string, unknown>> = [];
    vi.stubGlobal('fetch', vi.fn(async (_url: string, init: RequestInit) => {
      bodies.push(JSON.parse(String(init.body)) as Record<string, unknown>);
      return new Response(JSON.stringify({ message: { content: 'ok' } }), {
        status: 200,
        headers: { 'content-type': 'application/json' },
      });
    }));

    await chat({ url: 'http://127.0.0.1:11434', model: 'plain-model', messages: [] });
    expect(bodies).toHaveLength(1);
    expect(bodies[0].think).toBe(false);
  });

  it('drops images when the model rejects multimodal input', async () => {
    const bodies: Array<{ think: boolean; messages: Array<{ images?: string[] }> }> = [];
    vi.stubGlobal('fetch', vi.fn(async (_url: string, init: RequestInit) => {
      const body = JSON.parse(String(init.body));
      bodies.push(body);
      if (body.messages.some((m: { images?: string[] }) => m.images?.length)) {
        return new Response(JSON.stringify({ error: 'Multimodal data provided, but model does not support multimodal requests.' }), { status: 400 });
      }
      return new Response(JSON.stringify({ message: { content: 'ok' } }), {
        status: 200,
        headers: { 'content-type': 'application/json' },
      });
    }));

    const result = await chat({
      url: 'http://127.0.0.1:11434',
      model: 'text-only-model',
      messages: [{ role: 'user', content: 'what is on screen' }],
      images: ['BASE64'],
    });

    expect(result.content).toBe('ok');
    expect(bodies).toHaveLength(2);
    expect(bodies[0].messages[0].images).toEqual(['BASE64']);
    expect(bodies[1].messages[0].images).toBeUndefined();
  });

  it('sheds thinking and images in turn for a model that supports neither', async () => {
    const attempts: Array<{ think: boolean; hasImages: boolean }> = [];
    vi.stubGlobal('fetch', vi.fn(async (_url: string, init: RequestInit) => {
      const body = JSON.parse(String(init.body));
      const hasImages = body.messages.some((m: { images?: string[] }) => m.images?.length);
      attempts.push({ think: body.think, hasImages });
      if (body.think) {
        return new Response(JSON.stringify({ error: '"plain" does not support thinking' }), { status: 400 });
      }
      if (hasImages) {
        return new Response(JSON.stringify({ error: 'model does not support multimodal requests' }), { status: 400 });
      }
      return new Response(JSON.stringify({ message: { content: 'ok' } }), {
        status: 200,
        headers: { 'content-type': 'application/json' },
      });
    }));

    const result = await chat({
      url: 'http://127.0.0.1:11434',
      model: 'plain',
      messages: [{ role: 'user', content: 'go' }],
      thinking: true,
      images: ['BASE64'],
    });

    expect(result.content).toBe('ok');
    expect(attempts).toEqual([
      { think: true, hasImages: true },
      { think: false, hasImages: true },
      { think: false, hasImages: false },
    ]);
  });

  it('parses models correctly when fetch returns 200', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => new Response(JSON.stringify({
      models: [{ name: 'llama3:latest' }, { name: 'qwen2.5:latest' }],
    }), { status: 200, headers: { 'content-type': 'application/json' } })));

    const result = await ping('http://127.0.0.1:11434');
    expect(result.ok).toBe(true);
    expect(result.models).toEqual(['llama3:latest', 'qwen2.5:latest']);
  });

  it('separates <think> tags from content during chat', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => new Response(JSON.stringify({
      model: 'deepseek-r1:14b',
      message: {
        content: '<think>Let me click the search bar.</think>```json\n{"name":"click","arguments":{"ref":"@e2"}}\n```',
      },
    }), { status: 200, headers: { 'content-type': 'application/json' } })));

    const result = await chat({
      url: 'http://127.0.0.1:11434',
      model: 'deepseek-r1:14b',
      messages: [{ role: 'user', content: 'Search' }],
    });

    expect(result.thinking).toBe('Let me click the search bar.');
    expect(result.toolCall).toEqual({
      name: 'click',
      arguments: { ref: '@e2' },
    });
  });

  it('omits tool schemas for text-only calls', async () => {
    const fetchMock = vi.fn(async (_url: string, _init?: RequestInit) => new Response(JSON.stringify({
      model: 'test-model',
      message: { content: 'summary' },
    }), { status: 200, headers: { 'content-type': 'application/json' } }));
    vi.stubGlobal('fetch', fetchMock);

    await chat({
      url: 'http://127.0.0.1:11434',
      model: 'test-model',
      messages: [{ role: 'user', content: 'Summarize' }],
      tools: [],
    });

    const body = JSON.parse(String((fetchMock.mock.calls[0][1] as RequestInit).body));
    expect(body).not.toHaveProperty('tools');
  });
});

import { describe, expect, it } from 'vitest';
import { classifyTask, MAX_AUTO_SKILLS } from './skills';

const ids = (goal: string) => classifyTask(goal).map((c) => c.id);

describe('skill routing', () => {
  it('never injects more than MAX_AUTO_SKILLS playbooks', () => {
    const goals = [
      'найди цены на ноутбуки и собери в гугл таблицы',
      'сравни цены на iphone 15 в трёх магазинах',
      'открой три вкладки и сравни информацию',
      'extract all product prices and list them',
      'скачай отчёт в pdf',
    ];
    for (const goal of goals) {
      expect(ids(goal).length).toBeLessThanOrEqual(MAX_AUTO_SKILLS);
    }
  });

  it('does not match a keyword in the middle of another word', () => {
    // "форма" used to match "ин-ФОРМА-цию", pulling form-filler into research goals.
    expect(ids('проверь информацию о дате релиза')).not.toContain('form-filler');
    expect(ids('погугли информацию о новых релизах и сравни источники')).not.toContain('form-filler');
    expect(ids('открой три вкладки и сравни информацию')).not.toContain('form-filler');
  });

  it('does not route documentation or downloads to the form filler', () => {
    // "документ" as a bare keyword fired on documentation and on report
    // downloads; filling a document is always phrased with a verb.
    expect(ids('найди в документации react как работает useEffect')).not.toContain('form-filler');
    expect(ids('download the annual report document')).not.toContain('form-filler');
    expect(ids('заполни pdf форму заявления')).toContain('form-filler');
  });

  it('still matches inflected forms of a keyword', () => {
    // The tail stays open: "поиск" → "поиска", "search" → "searching".
    expect(ids('заполни анкету на сайте')).toContain('form-filler');
    expect(ids('searching for benchmark results')).toContain('researcher');
  });

  it('requires a short keyword to be the whole word', () => {
    // "поле" used to fire on "полезные" and "полет"; "form" on "format".
    for (const goal of ['найди полезные статьи про rust', 'узнай когда полет в Берлин']) {
      expect(ids(goal)).not.toContain('form-filler');
    }
    expect(ids('check the data format of the export')).not.toContain('form-filler');
    // The whole-word rule must not cost the keywords their inflected forms.
    expect(ids('какие поля обязательны в этой форме')).toContain('form-filler');
    expect(ids('reformat the list of tabs')).toContain('tab-manager');
  });

  it('ranks keyword hits above semantic matches', () => {
    const results = classifyTask('скачай отчёт в pdf');
    expect(results[0].id).toBe('file-downloader');
    expect(results[0].score).toBeGreaterThan(0.55);
  });

  it('ranks a multi-word hit above a single common verb', () => {
    const results = classifyTask('найди цены на ноутбуки и собери в гугл таблицы');
    expect(results[0].id).toBe('google-sheets');
    expect(results.map((r) => r.id)).not.toContain('researcher');
  });

  it('does not route documentation or downloads to the form filler', () => {
    // A bare "документ"/"document" keyword fired on documentation and on report
    // downloads alike; filling one is always phrased with a verb.
    expect(ids('найди в документации react как работает useEffect')).not.toContain('form-filler');
    expect(ids('download the annual report document')).not.toContain('form-filler');
    expect(ids('заполни pdf форму заявления')).toContain('form-filler');
  });

  it('routes site-scoped goals to site-search', () => {
    expect(ids('найди в документации react как работает useEffect')).toContain('site-search');
    expect(ids('find the pricing page on their website and list the tiers')).toContain('site-search');
    expect(ids('проверь наличие товара в каталоге магазина')).toContain('site-search');
  });

  it('does not let a short generic phrase outrank a specific skill', () => {
    // "на сайте" is said in half of all goals; it must not beat two direct hits.
    const results = classifyTask('заполни анкету на сайте');
    expect(results[0].id).toBe('form-filler');
  });

  it('routes claim verification to fact-checker instead of researcher', () => {
    for (const goal of [
      'правда ли что компания X закрыла офис в Берлине',
      'is it true that the CEO resigned last week',
    ]) {
      expect(ids(goal)).toContain('fact-checker');
      expect(ids(goal)).not.toContain('researcher');
    }
  });

  it('keeps the better-scoring skill of a conflicting pair', () => {
    const custom = [
      {
        id: 'fixture-checker',
        name: 'Fixture Checker',
        summary: 'Verify a single claim against its primary source',
        risk: 'safe' as const,
        domains: ['*'],
        keywords: ['правда ли', 'верификация факта'],
        conflictsWith: ['researcher'],
        prompt: '[SKILL: fixture-checker] Find the primary source.',
        isCustom: true,
        enabled: true,
        createdAt: Date.now(),
      },
    ];

    const results = classifyTask('правда ли что компания закрыла офис, найди источники', custom);
    expect(results.map((r) => r.id)).toContain('fixture-checker');
    expect(results.map((r) => r.id)).not.toContain('researcher');
  });
});

import { describe, expect, it } from 'vitest';
import { BUILT_IN_SKILLS, classifyTask, enabledSkillPrompts, getSkill, isKnownSkill } from './skills';

describe('skills', () => {
  it('defines valid built-in skills with required fields', () => {
    expect(BUILT_IN_SKILLS.length).toBeGreaterThanOrEqual(10);
    for (const skill of BUILT_IN_SKILLS) {
      expect(skill.id).toBeDefined();
      expect(skill.name).toBeDefined();
      expect(skill.prompt).toContain(`[SKILL: ${skill.id}]`);
      expect(skill.keywords.length).toBeGreaterThan(0);
    }
  });

  it('classifies tasks automatically using English keywords', () => {
    const sheetResults = classifyTask('create a spreadsheet and fill data in google sheets');
    expect(sheetResults.some((s) => s.id === 'google-sheets')).toBe(true);

    const extractResults = classifyTask('extract all product prices and list them');
    expect(extractResults.some((s) => s.id === 'data-extractor')).toBe(true);

    const searchResults = classifyTask('search for the latest AI agent papers and compare findings');
    expect(searchResults.some((s) => s.id === 'researcher')).toBe(true);
  });

  it('classifies tasks automatically using Russian keywords', () => {
    const sheetResults = classifyTask('найди цены на ноутбуки и собери в гугл таблицы');
    expect(sheetResults.some((s) => s.id === 'google-sheets')).toBe(true);
    expect(sheetResults.some((s) => s.id === 'data-extractor')).toBe(true);

    const researchResults = classifyTask('погугли информацию о новых релизах и сравни источники');
    expect(researchResults.some((s) => s.id === 'researcher')).toBe(true);

    const formResults = classifyTask('заполни анкету на сайте');
    expect(formResults.some((s) => s.id === 'form-filler')).toBe(true);

    const loginResults = classifyTask('войти в личный кабинет через пароль');
    expect(loginResults.some((s) => s.id === 'login-assistant')).toBe(true);
  });

  it('never auto-classifies high risk skills', () => {
    // No built-in skill carries this risk any more — social-poster used to, which meant a
    // goal about posting matched nothing and the model worked without a playbook. The rule
    // itself still holds for anything a user marks high.
    const custom = [
      {
        id: 'wire-transfer',
        name: 'Wire Transfer',
        summary: 'Move money between accounts',
        risk: 'high' as const,
        domains: ['*'],
        keywords: ['wire transfer', 'переведи деньги'],
        prompt: '[SKILL: wire-transfer] Never.',
        isCustom: true,
        enabled: true,
        createdAt: Date.now(),
      },
    ];

    const results = classifyTask('make a wire transfer to the supplier', custom);
    expect(results.some((s) => s.id === 'wire-transfer')).toBe(false);
  });

  it('routes a posting goal to the social poster', () => {
    expect(classifyTask('publish a post on linkedin').map((s) => s.id)).toContain('social-poster');
    expect(classifyTask('опубликуй пост в linkedin').map((s) => s.id)).toContain('social-poster');
  });

  it('generates combined prompts for enabled skills', () => {
    const prompts = enabledSkillPrompts(['google-sheets', 'data-extractor']);
    expect(prompts).toContain('[SKILL: google-sheets]');
    expect(prompts).toContain('[SKILL: data-extractor]');
  });

  it('validates known skill IDs correctly', () => {
    expect(isKnownSkill('google-sheets')).toBe(true);
    expect(isKnownSkill('unknown-skill')).toBe(false);
    expect(getSkill('google-sheets')?.name).toBe('Google Sheets Operator');
  });

  it('supports asynchronous neural classification', async () => {
    const { classifyTaskNeural } = await import('./skills');
    const results = await classifyTaskNeural('заполни анкету');
    expect(results.some((s) => s.id === 'form-filler')).toBe(true);
  });

  it('supports custom user-defined skills', () => {
    const custom = [
      {
        id: 'crm-helper',
        name: 'CRM Helper',
        summary: 'Handles corporate CRM leads',
        risk: 'safe' as const,
        domains: ['crm.internal'],
        keywords: ['crm', 'лид', 'сделка'],
        prompt: '[SKILL: crm-helper] Always assign manager',
        isCustom: true,
        enabled: true,
        createdAt: Date.now(),
      },
    ];

    const results = classifyTask('добавь нового лида в crm', custom);
    expect(results.some((s) => s.id === 'crm-helper')).toBe(true);

    expect(isKnownSkill('crm-helper', custom)).toBe(true);
    expect(getSkill('crm-helper', custom)?.prompt).toContain('Always assign manager');
    expect(enabledSkillPrompts(['crm-helper'], custom)).toContain('[SKILL: crm-helper]');
  });
});

import { describe, expect, it } from 'vitest';
import { AGENT_TOOLS, selectAgentTools } from './tools';

describe('tool palette benchmark', () => {
  it('cuts schema payload for a direct browser action by more than half', () => {
    const selected = selectAgentTools({
      goal: 'Click the account button',
      firstStep: true,
      snapshot: { url: 'https://example.com', nodes: [] },
    });
    const fullBytes = JSON.stringify(AGENT_TOOLS).length;
    const selectedBytes = JSON.stringify(selected).length;
    const reduction = 1 - selectedBytes / fullBytes;

    console.log(
      `Tool schemas: ${AGENT_TOOLS.length} -> ${selected.length}; ` +
      `${fullBytes} -> ${selectedBytes} chars (${Math.round(reduction * 100)}% reduction)`,
    );

    expect(selected.length).toBeLessThan(AGENT_TOOLS.length / 2);
    expect(reduction).toBeGreaterThan(0.5);
  });
});

import { describe, expect, it } from 'vitest';
import { shouldAttachScreenshot } from './vision-policy';
import { ERROR_PAGE_DOM_HASH_PREFIX } from './page-state';
import { DEFAULT_SETTINGS } from './types';
import type { A11ySnapshot } from './types';

function snapshot(overrides: Partial<A11ySnapshot>): A11ySnapshot {
  return {
    url: 'https://a.example/',
    title: 'A page',
    viewport: { w: 1280, h: 720, scrollX: 0, scrollY: 0 },
    nodes: [],
    textSnippets: [],
    domHash: 'abc123',
    takenAt: 0,
    ...overrides,
  };
}

describe('vision on an unreadable page', () => {
  it('spends no screenshot on a tab parked on the error page', () => {
    // The stand-in snapshot has no nodes, which would otherwise match the canvas/shadow-DOM rule
    // and photograph Chrome's error page — the same few words every time.
    const decision = shouldAttachScreenshot(
      snapshot({
        url: 'http://127.0.0.1:1/roster',
        viewport: { w: 0, h: 0, scrollX: 0, scrollY: 0 },
        domHash: `${ERROR_PAGE_DOM_HASH_PREFIX}http://127.0.0.1:1/roster`,
      }),
      DEFAULT_SETTINGS,
      { stepIndex: 3 },
    );

    expect(decision.attach).toBe(false);
    expect(decision.reason).toContain('error page');
  });

  it('still photographs a genuinely node-less page such as a canvas app', () => {
    expect(shouldAttachScreenshot(snapshot({}), DEFAULT_SETTINGS, { stepIndex: 3 }).attach).toBe(true);
  });

  it('skips vision when the accessibility tree is enough', () => {
    // Measured over 1077 recorded steps: only 14.4% attach a screenshot. The default path is
    // already the cheap one, and this pins that so it stays true.
    const decision = shouldAttachScreenshot(
      snapshot({ nodes: [{ ref: '@e1', role: 'heading', name: 'Invoice 88' }] as A11ySnapshot['nodes'] }),
      DEFAULT_SETTINGS,
      { stepIndex: 3 },
    );

    expect(decision.attach).toBe(false);
    expect(decision.reason).toBe('a11y sufficient');
  });
});

#!/usr/bin/env node
import { readFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const evalDir = path.join(root, 'evals');
const fixtureDir = path.join(evalDir, 'fixtures');
const tasksPath = path.join(evalDir, 'tasks.json');

const tasks = JSON.parse(await readFile(tasksPath, 'utf8'));
const errors = [];
const ids = new Set();
const cyrillic = /[А-Яа-я]/;

if (!Array.isArray(tasks) || tasks.length === 0) {
  errors.push('evals/tasks.json must contain a non-empty array');
}

for (const task of tasks) {
  const label = task?.id ?? '(missing id)';

  if (!task.id || typeof task.id !== 'string') errors.push(`${label}: missing string id`);
  if (ids.has(task.id)) errors.push(`${label}: duplicate id`);
  ids.add(task.id);

  for (const field of ['title', 'fixture', 'prompt']) {
    if (!task[field] || typeof task[field] !== 'string') errors.push(`${label}: missing string ${field}`);
  }

  for (const field of ['expectedEvidence', 'expectedAnswerIncludes', 'traceAssertions', 'failureModes']) {
    if (!Array.isArray(task[field]) || task[field].length === 0) {
      errors.push(`${label}: ${field} must be a non-empty array`);
    }
  }

  const textBlob = JSON.stringify(task);
  if (cyrillic.test(textBlob)) errors.push(`${label}: eval metadata must be English-only`);

  const fixtures = [task.fixture, ...(task.relatedFixtures ?? [])];
  for (const fixture of fixtures) {
    const fixturePath = path.join(fixtureDir, fixture);
    if (!existsSync(fixturePath)) {
      errors.push(`${label}: missing fixture ${fixture}`);
    }
  }

  const existingFixtures = fixtures.filter((fixture) => existsSync(path.join(fixtureDir, fixture)));
  if (existingFixtures.length > 0) {
    const htmlParts = await Promise.all(existingFixtures.map((fixture) => readFile(path.join(fixtureDir, fixture), 'utf8')));
    const html = htmlParts.join('\n');
    for (const evidence of task.expectedEvidence ?? []) {
      if (!html.toLowerCase().includes(String(evidence).toLowerCase())) {
        errors.push(`${label}: fixtures do not contain expected evidence "${evidence}"`);
      }
    }
    // A compromise marker has to name text the fixture actually carries, or the eval
    // asserts against an attack that is not on the page.
    for (const forbidden of task.forbiddenAnswerIncludes ?? []) {
      if (!html.toLowerCase().includes(String(forbidden).toLowerCase())) {
        errors.push(`${label}: fixtures do not contain forbidden text "${forbidden}"`);
      }
    }
  }

  // The trap this catches: expecting "29 EUR" while forbidding "299 EUR" passes a fully
  // compromised answer, because the honest string sits inside the hostile one.
  for (const forbidden of task.forbiddenAnswerIncludes ?? []) {
    for (const expected of task.expectedAnswerIncludes ?? []) {
      const f = String(forbidden).toLowerCase();
      const e = String(expected).toLowerCase();
      if (f.includes(e) || e.includes(f)) {
        errors.push(`${label}: expected "${expected}" and forbidden "${forbidden}" overlap; a compromised answer would pass`);
      }
    }
  }
}

if (errors.length > 0) {
  console.error('Eval fixture validation failed:');
  for (const error of errors) console.error(`- ${error}`);
  process.exit(1);
}

console.log(`Eval fixtures ok: ${tasks.length} tasks, ${ids.size} unique ids`);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { createServer } from 'node:http';
import vm from 'node:vm';

const source = await readFile(new URL('./eval-extension.mjs', import.meta.url), 'utf8');
const proxySource = source.slice(source.indexOf('async function startOllamaProxy()'), source.indexOf('\nfunction run('));

test('Ollama proxy fixes the destination and rejects redirects and unexpected paths', async () => {
  const calls = [];
  const context = vm.createContext({
    createServer, URL, Buffer, process,
    fetch: async (url, options) => {
      calls.push({ url: url.href, redirect: options.redirect });
      return { status: 200, headers: new Headers(), body: null };
    },
  });
  const server = await vm.runInContext(`${proxySource}\nstartOllamaProxy()`, context);
  try {
    const response = await fetch(`${server.origin}//evil.test/api/chat`);
    assert.equal(response.status, 200);
    const target = new URL(process.env.WEBOPERATOR_OLLAMA_URL ?? 'http://127.0.0.1:11434');
    assert.equal(calls[0].url, `${target.origin}/api/chat`);
    assert.equal(calls[0].redirect, 'error');
    assert.equal((await fetch(`${server.origin}/admin`)).status, 404);
    assert.equal(calls.length, 1);
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
});

test('Ollama proxy does not expose upstream error details', async () => {
  const context = vm.createContext({ createServer, URL, Buffer, process, fetch: async () => { throw new Error('secret internal details'); } });
  const server = await vm.runInContext(`${proxySource}\nstartOllamaProxy()`, context);
  try {
    const response = await fetch(`${server.origin}/api/chat`);
    assert.equal(response.status, 502);
    assert.equal(await response.text(), 'Ollama upstream request failed');
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
});

