/**
 * Answer a follow-up question about a finished or interrupted task using only
 * what that run collected. No browser action is taken: the point is to get
 * more out of work already done, including work the user cut short.
 */
async function answerFromTrace(id: string, question: string): Promise<{ ok: boolean; answer?: string; error?: string }> {
  const trimmed = question.trim();
  if (!trimmed) return { ok: false, error: 'Question is empty.' };

  const task = await getTask(id);
  if (!task) return { ok: false, error: 'Task not found.' };
  task.steps = await loadSteps(id);

  const settings = await getSettings();
  const work = collectWork(task);
  const prompt = buildTraceQuestionPrompt(task.goal, work, trimmed);

  try {
    const resp = await requestModelResponse(settings, {
      url: settings.ollamaUrl,
      model: resolveOllamaModel(settings.ollamaModel, undefined),
      thinking: false,
      messages: [{ role: 'user', content: prompt }],
    });
    const answer = resp.content.trim();
    if (!answer) return { ok: false, error: 'The model returned an empty answer.' };
    return { ok: true, answer };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

import type { A11ySnapshot, Settings, VisualTokenBudget } from './types';
import { isErrorPageSnapshot } from './page-state';

export interface VisionContext {
  stepIndex: number;
  requestedByModel?: boolean;
  isIframeOnly?: boolean;
  lastStepFailed?: boolean;
}

export interface VisionDecision {
  attach: boolean;
  reason: string;
  visualTokens: <REDACTED>
  isVerification: boolean;
}

export function shouldAttachScreenshot(
  snapshot: A11ySnapshot,
  settings: Settings,
  ctx: VisionContext,
): VisionDecision {
  const base: VisualTokenBudget = <REDACTED>
  const verify: VisualTokenBudget = <REDACTED>

  if (settings.screenshotPolicy === 'never') return { attach: false, reason: 'policy=never', visualTokens: <REDACTED> isVerification: false };
  if (settings.screenshotPolicy === 'always') return { attach: true, reason: 'policy=always', visualTokens: <REDACTED> isVerification: false };

  // A page that cannot be read at all has nothing to photograph either: Chrome's error page is
  // the same few words every time, and spending a screenshot on it buys nothing.
  if (isErrorPageSnapshot(snapshot))
    return { attach: false, reason: 'tab is on an error page — nothing to see', visualTokens: <REDACTED> isVerification: false };
  if (snapshot.nodes.length === 0)
    return { attach: true, reason: 'empty a11y snapshot (canvas/shadow DOM) — read the page from the screenshot, refs are unavailable', visualTokens: <REDACTED> isVerification: true };
  if (ctx.requestedByModel)
    return { attach: true, reason: 'model requested visual verification', visualTokens: <REDACTED> isVerification: true };
  if (ctx.isIframeOnly)
    return { attach: true, reason: 'iframe without a11y access', visualTokens: <REDACTED> isVerification: true };
  if (ctx.lastStepFailed)
    return { attach: true, reason: 'retry after failed step', visualTokens: <REDACTED> isVerification: true };

  return { attach: false, reason: 'a11y sufficient', visualTokens: <REDACTED> isVerification: false };
}

export function isDomainAllowed(url: string, settings: Settings): { allowed: boolean; reason?: string } {
  let host: string;
  try { host = new URL(url).hostname; } catch { return { allowed: false, reason: 'invalid URL' }; }
  if (settings.blacklist.some((pat) => matches(host, pat))) return { allowed: false, reason: `blocked by blacklist (${host})` };
  if (settings.whitelist.length > 0 && !settings.whitelist.some((pat) => matches(host, pat))) {
    return { allowed: false, reason: `not in whitelist (${host})` };
  }
  return { allowed: true };
}

function matches(host: string, pattern: string): boolean {
  const p = pattern.trim().toLowerCase();
  if (!p) return false;
  const h = host.toLowerCase();
  if (p.startsWith('*.')) return h === p.slice(2) || h.endsWith(p.slice(1));
  return h === p || h.endsWith(`.${p}`);
}
